const RECENCY_HOURS = 16;
const MIN_SIMILARITY = 0.55;
const MAX_ARTICLES = 100;
const now = new Date();

const context = $('Determine Digest Period').first().json;

const SOURCE_MAP = [
  ['bbci.co.uk', 'BBC Sport'],
  ['skysports.com', 'Sky Sports'],
  ['theguardian.com', 'The Guardian'],
  ['espn.com', 'ESPN'],
  ['goal.com', 'Goal.com'],
  ['uefa.com', 'UEFA'],
  ['fifa.com', 'FIFA'],
];

function resolveSource(link) {
  if (!link) return 'Unknown Source';
  const lower = String(link).toLowerCase();
  const hit = SOURCE_MAP.find(([host]) => lower.includes(host));
  if (hit) return hit[1];
  try {
    return new URL(link).hostname.replace(/^www\./, '');
  } catch (e) {
    return 'Unknown Source';
  }
}

function normalizeTitle(title) {
  return (title || '')
    .toString()
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenSet(normalized) {
  return new Set(normalized.split(' ').filter((w) => w.length > 2));
}

function similarity(a, b) {
  if (a.size === 0 || b.size === 0) return 0;
  let shared = 0;
  for (const token of a) {
    if (b.has(token)) shared += 1;
  }
  return shared / Math.min(a.size, b.size);
}

const rawItems = items
  .map((item) => item.json)
  .filter((json) => json && json.title && json.link && !json.error);

const withMeta = rawItems.map((json) => {
  const publishedRaw = json.isoDate || json.pubDate || null;
  const publishedDate = publishedRaw ? new Date(publishedRaw) : null;
  const validDate = publishedDate && !isNaN(publishedDate.getTime());
  const normalized = normalizeTitle(json.title);
  return {
    title: String(json.title).trim(),
    link: json.link,
    source: resolveSource(json.link),
    publishedAt: validDate ? publishedDate.toISOString() : null,
    publishedTimestamp: validDate ? publishedDate.getTime() : null,
    snippet: String(json.contentSnippet || json.content || '').replace(/\s+/g, ' ').trim().slice(0, 400),
    tokens: tokenSet(normalized),
  };
});

const cutoff = now.getTime() - RECENCY_HOURS * 60 * 60 * 1000;
const recent = withMeta.filter((a) => a.publishedTimestamp === null || a.publishedTimestamp >= cutoff);

recent.sort((a, b) => (b.publishedTimestamp || 0) - (a.publishedTimestamp || 0));

const kept = [];
for (const article of recent) {
  const isDuplicate = kept.some((k) => similarity(k.tokens, article.tokens) >= MIN_SIMILARITY);
  if (!isDuplicate) kept.push(article);
}

const limited = kept.slice(0, MAX_ARTICLES).map(({ tokens, ...rest }) => rest);

return [
  {
    json: {
      periodLabel: context.periodLabel,
      periodEmoji: context.periodEmoji,
      runDate: context.runDate,
      totalCollected: rawItems.length,
      totalAfterDedup: limited.length,
      articles: limited,
    },
  },
];

