const MAX_LEN = 3500;

const result = $json.output || $json;
const stories = Array.isArray(result.stories) ? result.stories.slice(0, 10) : [];
const periodLabel = result.period_label || $('Determine Digest Period').first().json.periodLabel;
const numberEmojis = ['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣','🔟'];
const divider = '━━━━━━━━━━━━━━';

function formatTime(iso) {
  if (!iso) return 'غير محدد';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return String(iso);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())} UTC`;
}

const header = ['🏆 أهم أخبار كرة القدم', `📅 ${periodLabel}`, divider].join('\n');
const footer = '🤖 تم الإنشاء تلقائيًا بواسطة n8n + OpenAI';

const storyBlocks = [];
if (stories.length === 0) {
  storyBlocks.push(['⚠️ لم يتم العثور على أخبار تستحق النشر في هذه الدورة.', divider].join('\n'));
} else {
  stories.forEach((story, idx) => {
    const num = numberEmojis[idx] || `${idx + 1}.`;
    const block = [
      `${num} ⚽ ${story.title_ar || 'بدون عنوان'}`,
      `📰 ${story.summary_ar || ''}`,
      `🌍 ${story.source || 'غير معروف'}`,
      `🕒 ${formatTime(story.published_at)}`,
      `🔗 ${story.link || ''}`,
      divider,
    ].join('\n');
    storyBlocks.push(block);
  });
}

// Telegram hard-limits sendMessage text to 4096 chars; pack story blocks
// into multiple messages under that limit rather than truncating content.
const chunks = [];
let current = header;
for (const block of storyBlocks) {
  const candidate = current + '\n' + block;
  if (candidate.length > MAX_LEN && current !== header) {
    chunks.push(current);
    current = header + '\n' + block;
  } else if (candidate.length > MAX_LEN) {
    chunks.push(current + '\n' + block.slice(0, Math.max(0, MAX_LEN - current.length - 1)));
    current = header;
  } else {
    current = candidate;
  }
}
chunks.push(current);

const lastIdx = chunks.length - 1;
if ((chunks[lastIdx] + '\n' + footer).length <= MAX_LEN) {
  chunks[lastIdx] = chunks[lastIdx] + '\n' + footer;
} else {
  chunks.push(footer);
}

const totalParts = chunks.length;
const finalChunks = chunks.map((c, i) => (totalParts > 1 ? `📄 (${i + 1}/${totalParts})\n` + c : c));

// One item per chunk -- the downstream Telegram node sends one message per item.
return finalChunks.map((messageText) => ({ json: { messageText, storyCount: stories.length, periodLabel } }));

